<script setup lang="ts">
import {ref} from 'vue';import {projectTemplates,type ProjectTemplate} from '../templates/library';
defineProps<{userTemplates:ProjectTemplate[]}>();const emit=defineEmits<{close:[];select:[template:ProjectTemplate];save:[name:string];remove:[id:string]}>();const name=ref('');
function save(){const value=name.value.trim();if(!value)return;emit('save',value);name.value='';}
</script>
<template><div class="modal-backdrop" @click.self="emit('close')"><section class="template-dialog"><header><div><span class="eyebrow">TEMPLATES</span><h3>模板库</h3></div><button @click="emit('close')">×</button></header><div class="template-save"><input v-model="name" class="field" placeholder="当前项目模板名称" @keyup.enter="save"><button class="primary-command" :disabled="!name.trim()" @click="save">保存当前</button></div><p v-if="userTemplates.length">我的模板</p><div v-if="userTemplates.length" class="template-grid"><div v-for="item in userTemplates" :key="item.id" class="user-template"><button @click="emit('select',item)"><span class="template-preview"><i v-for="height in [48,72,38,82,60]" :key="height" :style="{height:`${height}%`}"></i></span><strong>{{item.name}}</strong><small>{{item.description}}</small></button><button class="template-remove" title="删除模板" @click="emit('remove',item.id)">×</button></div></div><p>内置模板</p><div class="template-grid"><button v-for="item in projectTemplates" :key="item.id" @click="emit('select',item)"><span class="template-preview"><i v-for="height in [35,65,48,78,58]" :key="height" :style="{height:`${height}%`}"></i></span><strong>{{item.name}}</strong><small>{{item.description}}</small></button></div></section></div></template>
